<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Event;

use Override;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\UserGroupMembership;
use Civi\Lughauth\Shared\Event\PublicEvent;

class UserGroupMembershipUpdateEvent extends UserGroupMembershipEvent implements PublicEvent
{
    public function __construct(
        UserGroupMembership $payload,
        public readonly UserGroupMembership $original
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'user-group-membership.update';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
